template<>
bool sevalue_to_native(const se::Value &from, b2Profile * to, se::Object *ctx)
{
    assert(from.isObject());
    se::Object *json = from.toObject();
    auto* data = reinterpret_cast<b2Profile*>(json->getPrivateData());
    if (data) {
        *to = *data;
        return true;
    }
    se::Value field;
    bool ok = true;
    
    json->getProperty("step", &field, true);
    if (!field.isNullOrUndefined()) {
        ok &= sevalue_to_native(field, &(to->step), ctx);
    }
    
    
    json->getProperty("collide", &field, true);
    if (!field.isNullOrUndefined()) {
        ok &= sevalue_to_native(field, &(to->collide), ctx);
    }
    
    
    json->getProperty("solve", &field, true);
    if (!field.isNullOrUndefined()) {
        ok &= sevalue_to_native(field, &(to->solve), ctx);
    }
    
    
    json->getProperty("solveInit", &field, true);
    if (!field.isNullOrUndefined()) {
        ok &= sevalue_to_native(field, &(to->solveInit), ctx);
    }
    
    
    json->getProperty("solveVelocity", &field, true);
    if (!field.isNullOrUndefined()) {
        ok &= sevalue_to_native(field, &(to->solveVelocity), ctx);
    }
    
    
    json->getProperty("solvePosition", &field, true);
    if (!field.isNullOrUndefined()) {
        ok &= sevalue_to_native(field, &(to->solvePosition), ctx);
    }
    
    
    json->getProperty("broadphase", &field, true);
    if (!field.isNullOrUndefined()) {
        ok &= sevalue_to_native(field, &(to->broadphase), ctx);
    }
    
    
    json->getProperty("solveTOI", &field, true);
    if (!field.isNullOrUndefined()) {
        ok &= sevalue_to_native(field, &(to->solveTOI), ctx);
    }
    
    
    return ok;
}


